// These paths are the optimized single-path form (cutouts as nested subpaths)
// and need the even-odd fill rule; the rest are the repository's originals.
const EVENODD = new Set(["arrowUndo", "arrowRedo", "textBold", "textItalic", "textStrikethrough", "code", "checkboxChecked", "table", "link", "flow"]);

/** Inline SVG for a Fluent icon; `size` in px (defaults to 16). */
export function icon(name, { size = 16, className = "" } = {}) {
  const paths = PATHS[name];
  if (!paths) throw new Error(`unknown icon ${name}`);
  const rule = EVENODD.has(name) ? ' fill-rule="evenodd" clip-rule="evenodd"' : "";
  return `<svg class="fi${className ? ` ${className}` : ""}" width="${size}" height="${size}" viewBox="0 0 16 16" fill="none" aria-hidden="true">${paths.map((d) => `<path d="${d}" fill="currentColor"${rule}/>`).join("")}</svg>`;
}

export const ICON_NAMES = Object.keys(PATHS);
